using System.Text.Json;
using UnscRelay.Core;
internal static class SnapshotIntegrityChecks
{
 public static int Run(){var count=0;void Check(bool good,string label){if(!good)throw new Exception(label);count++;Console.WriteLine("PASS integrity: "+label);}var records=JsonSerializer.SerializeToElement(new[]{new{info=new{id="key-fixture",kind="ssh-key",name="Fixture key"},content=""}});var data=new AppData{Profiles=[new(){Name="First fixture",Host="fixture.invalid",Username="fixture",KeyId="key-fixture",PasswordId="missing"},new(){Name="Second fixture",Host="fixture.invalid",Username="fixture",KeyId="missing"}],Workspaces=[new("Workspace fixture","tabs",["missing-profile"])]};var snapshot=new PortableSnapshot(2,records,data,[]);var before=JsonSerializer.Serialize(snapshot,VaultSyncCrypto.Json);var report=SnapshotIntegrity.Inspect(snapshot);Check(report.Records==1&&report.Profiles==2&&report.HostKeys==0,"integrity report contains only structural counts and references");Check(report.WarningCount==3&&report.Findings.Select(value=>value.Code).ToHashSet().SetEquals(["missing-key","missing-password","missing-profile"]),"missing saved credentials and workspace profiles are reported separately");Check(JsonSerializer.Serialize(snapshot,VaultSyncCrypto.Json)==before,"inspection does not alter the snapshot or repair data automatically");var complete=SnapshotIntegrity.Inspect(snapshot with{Data=new AppData{Profiles=[new(){Name="Complete fixture",Host="fixture.invalid",Username="fixture",KeyId="key-fixture"}]}});Check(complete.WarningCount==0,"present credential references do not produce a warning");var many=SnapshotIntegrity.Inspect(snapshot with{Data=new AppData{Profiles=Enumerable.Range(0,150).Select(index=>new ConnectionProfile{Name="Fixture "+index,Host="fixture.invalid",Username="fixture",KeyId="missing"}).ToList()}});Check(many.WarningCount==150&&many.Findings.Count==100,"full warning count is retained while the displayed finding list is bounded");Console.WriteLine("Snapshot integrity checks: "+count);return 0;}
}
